namespace A33.Instrument.Protocol;
public sealed class ModbusRtuTransport(Stream stream,byte slave=1) : IModbusTransport { public bool IsOpen=>true; public Task OpenAsync(CancellationToken ct)=>Task.CompletedTask; public async Task<ReadOnlyMemory<byte>> ExchangeAsync(ReadOnlyMemory<byte> request,CancellationToken ct){var source=request.Span;var payload=source.Length>0&&source[0]==slave?source[1..]:source;var frame=new byte[payload.Length+3];frame[0]=slave;payload.CopyTo(frame.AsSpan(1));ModbusCrc16.Append(frame);await stream.WriteAsync(frame,ct);await stream.FlushAsync(ct);var response=new byte[256];var n=await stream.ReadAsync(response,ct);if(n==0)throw new TimeoutException("RTU response timeout");if(n<5)throw new FormatException("short RTU response");if(!ModbusCrc16.Verify(response.AsSpan(0,n)))throw new FormatException("RTU CRC mismatch");if(response[0]!=slave)throw new FormatException("unexpected slave");return response.AsMemory(0,n).ToArray();} public Task CloseAsync()=>Task.CompletedTask; public ValueTask DisposeAsync()=>ValueTask.CompletedTask; }
